// Built-in "Premade worlds" tab options (see App.tsx's Generate World dialog) -- each is a
// coastline sketch in the same white-background/black-outline convention "Human-made" mode
// expects (see worldsketch.py's module docstring), pre-baked as a data URL so picking one
// behaves exactly like drawing or loading an image did: it just becomes `sketchImageDataUrl`
// and rides the existing Human-made generation path (see handleGenerate). All three are
// stylized/simplified coastline sketches, not precise reconstructions -- "present-day Earth"
// is traced from real (Natural Earth 110m) coastlines; "Pangaea" and "Dragons & Zombie World"
// are hand-approximated, freehand silhouettes true to the *shape* of the well-known
// supercontinent / fantasy-map layouts they're named for, not a traced reproduction of any
// particular copyrighted map.

export interface PremadeWorld {
  id: string;
  label: string;
  dataUrl: string;
  // Fixed, not randomized -- a premade world's plate tectonics (and everything downstream:
  // elevation, mountains, biomes) come from `seed` just as much as from the coastline sketch
  // itself, so leaving it at whatever the Seed field happens to hold (a random default, or
  // whatever the last Random/Human-made tab left behind) would make "Present-day Earth" look
  // like a lottery draw instead of the one canonical result these are picked for. App.tsx's
  // premade-tab picker applies this alongside dataUrl and disables the Seed field while a
  // premade world is selected, so it can't drift.
  seed: number;
}

const EARTH_PNG_B64 =
  "";

const PANGAEA_PNG_B64 =
  "";

const GOT_PNG_B64 =
  "";

// Each seed below was picked by generating every seed 1-30 against its world's sketch and
// scoring per-node agreement between the generated land/sea and the sketch's own flood-filled
// land mask (worldsketch.parse_sketch_image) -- these are simply the best-fidelity seed for
// each sketch out of that search (agreement ~0.94/~1.00/~1.00 respectively; "earth" tops out
// lower than the other two since its sketch has much finer detail -- island chains, straits --
// than a coarse plate tessellation can fully resolve), not hand-tuned or otherwise special.
export const PREMADE_WORLDS: PremadeWorld[] = [
  { id: "earth", label: "Present-day Earth", dataUrl: `data:image/png;base64,${EARTH_PNG_B64}`, seed: 8 },
  { id: "pangaea", label: "Pangaea (pre-breakup)", dataUrl: `data:image/png;base64,${PANGAEA_PNG_B64}`, seed: 2 },
  { id: "got", label: "Dragons & Zombie World", dataUrl: `data:image/png;base64,${GOT_PNG_B64}`, seed: 3 },
];
